package org.securemail.community.gateway600;
import org.securemail.community.core.*;
import org.securemail.community.protocol600.CommunityWire600;
import org.securemail.community.http.StrictJson;
import org.securemail.ecosystem.protocol.IdentityProtocol;
import java.nio.charset.StandardCharsets;
import java.util.*;
/** Identity consumes a two-party permit before SQL mutation. A failed later SQL mutation needs a new permit. */
final class CommunityCritical600 {
    record Receipt(String id,String kind,String payload,String approverCapability) { }
    private final CommunityStore store;private final CommunityIdentityBridge600 bridge;
    CommunityCritical600(CommunityStore store,CommunityIdentityBridge600 bridge)throws Exception {this.store=store;this.bridge=bridge;store.tx(db->{try(var s=db.createStatement()){s.execute("CREATE TABLE IF NOT EXISTS ecosystem_critical(id TEXT PRIMARY KEY,identity_id TEXT NOT NULL,kind TEXT NOT NULL,payload TEXT NOT NULL,initiator TEXT NOT NULL,expires INTEGER NOT NULL,state TEXT NOT NULL,revision INTEGER NOT NULL,approver_cap TEXT NOT NULL DEFAULT '')");}return null;});}
    private Map<String,Object> row(String id)throws Exception {return store.tx(db->{try(var q=db.prepareStatement("SELECT * FROM ecosystem_critical WHERE id=?")){q.setString(1,id);try(var r=q.executeQuery()){if(!r.next())throw CommunityException.missing();return Map.ofEntries(Map.entry("id",id),Map.entry("identityRequestId",r.getString("identity_id")),Map.entry("kind",r.getString("kind")),Map.entry("payload",r.getString("payload")),Map.entry("requester",r.getString("initiator")),Map.entry("expires",r.getLong("expires")),Map.entry("state",r.getString("state")),Map.entry("revision",r.getLong("revision")),Map.entry("approverCapability",r.getString("approver_cap")));}}});}
    Map<String,Object> metadata(String id)throws Exception {Map<String,Object> row=new LinkedHashMap<>(row(id));row.remove("approverCapability");row.put("identityOperation",CommunityWire600.criticalOperation((String)row.get("kind")));row.put("digest",CommunityStore.hex(CommunityStore.hash(((String)row.get("payload")).getBytes(StandardCharsets.UTF_8))));return row;}
    Map<String,Object> request(CommunityIdentityBridge600.Evidence e,Map<String,Object> args,Map<String,Object> auth)throws Exception {if(!(args.get("payload") instanceof Map<?,?> payload))throw CommunityException.invalid();String kind=Values.string(args,"kind",40),encoded=CanonicalJson.encode(payload);byte[] bytes=encoded.getBytes(StandardCharsets.UTF_8);if(bytes.length>32768)throw new CommunityException("LIMIT","Слишком большой запрос подтверждения");Map<String,Object> rpc=identityProof(e,auth);rpc.put("operation",CommunityWire600.criticalOperation(kind));rpc.put("payload",IdentityProtocol.b64(bytes));Map<String,Object> answer=bridge.rpc("criticalRequest",rpc);String identityId=IdentityProtocol.nonceValue(StrictJson.text(answer,"requestId",43));long expires=StrictJson.number(answer,"expiresAt",1,Long.MAX_VALUE);String id=UUID.randomUUID().toString();store.tx(db->{try(var d=db.prepareStatement("DELETE FROM ecosystem_critical WHERE expires<?")){d.setLong(1,System.currentTimeMillis()-86400000);d.executeUpdate();}try(var c=db.createStatement();var r=c.executeQuery("SELECT count(*) FROM ecosystem_critical")){r.next();if(r.getLong(1)>=10000)throw CommunityException.invalid();}try(var q=db.prepareStatement("INSERT INTO ecosystem_critical VALUES(?,?,?,?,?,?,'PENDING',1,'')")){q.setString(1,id);q.setString(2,identityId);q.setString(3,kind);q.setString(4,encoded);q.setString(5,e.cap.accountId);q.setLong(6,expires);q.executeUpdate();}store.audit(db,e.cap.accountId,"ECOSYSTEM_CRITICAL_REQUEST",id,kind);return null;});return Map.of("id",id,"expires",expires,"digest",CommunityStore.hex(CommunityStore.hash(bytes)),"revision",1);}
    Map<String,Object> approve(CommunityIdentityBridge600.Evidence e,Map<String,Object> args,Map<String,Object> auth)throws Exception {String id=Values.string(args,"id",36);Map<String,Object> record=row(id);if(!record.get("state").equals("PENDING")||record.get("requester").equals(e.cap.accountId)||((Number)record.get("revision")).longValue()!=Values.number(args,"revision")||(Long)record.get("expires")<=System.currentTimeMillis())throw CommunityException.denied();Map<String,Object> rpc=identityProof(e,auth);rpc.put("requestId",record.get("identityRequestId"));bridge.rpc("criticalApprove",rpc);store.tx(db->{try(var q=db.prepareStatement("UPDATE ecosystem_critical SET state='APPROVED',revision=2,approver_cap=? WHERE id=? AND state='PENDING' AND revision=1")){q.setString(1,e.capability);q.setString(2,id);if(q.executeUpdate()!=1)throw CommunityException.conflict();}store.audit(db,e.cap.accountId,"ECOSYSTEM_CRITICAL_APPROVE",id,"Independent Identity ADMIN proof");return null;});return Map.of("ok",true,"revision",2);}
    Receipt consume(CommunityIdentityBridge600.Evidence e,Map<String,Object> args,Map<String,Object> auth)throws Exception {String id=Values.string(args,"requestId",36);Map<String,Object> record=row(id);String payload=CanonicalJson.encode(CanonicalJson.operationFields(args));if(!record.get("state").equals("APPROVED")||!record.get("requester").equals(e.cap.accountId)||!payload.equals(record.get("payload"))||(Long)record.get("expires")<=System.currentTimeMillis())throw CommunityException.denied();Map<String,Object> rpc=identityProof(e,auth);rpc.put("requestId",record.get("identityRequestId"));rpc.put("operation",CommunityWire600.criticalOperation((String)record.get("kind")));rpc.put("payload",IdentityProtocol.b64(payload.getBytes(StandardCharsets.UTF_8)));bridge.rpc("criticalConsume",rpc);return new Receipt(id,(String)record.get("kind"),payload,(String)record.get("approverCapability"));}
    Object execute(CommunityIdentityBridge600.Evidence e,Receipt receipt,String actor,String id,String kind,String payload,CommunityStore.SqlWork<?> work)throws Exception {if(receipt==null||!receipt.id.equals(id)||!receipt.kind.equals(kind)||!receipt.payload.equals(payload)||!actor.equals(e.cap.accountId))throw CommunityException.denied();return store.tx(db->{bridge.recheck(e,true);if(!Boolean.TRUE.equals(bridge.rpc("isActive",Map.of("capability",receipt.approverCapability)).get("active")))throw CommunityException.denied();try(var q=db.prepareStatement("SELECT 1 FROM ecosystem_critical WHERE id=? AND state='APPROVED' AND expires>?")){q.setString(1,id);q.setLong(2,System.currentTimeMillis());try(var r=q.executeQuery()){if(!r.next())throw CommunityException.denied();}}Object result=work.run(db);bridge.recheck(e,true);if(!Boolean.TRUE.equals(bridge.rpc("isActive",Map.of("capability",receipt.approverCapability)).get("active")))throw CommunityException.denied();try(var q=db.prepareStatement("UPDATE ecosystem_critical SET state='EXECUTED',revision=3 WHERE id=? AND state='APPROVED'")){q.setString(1,id);if(q.executeUpdate()!=1)throw CommunityException.conflict();}store.audit(db,actor,"ECOSYSTEM_CRITICAL_EXECUTED",id,kind);return result;});}
    Map<String,Object> list(Map<String,Object> args)throws Exception {String after=Values.optional(args,"after",36);long limit=args.containsKey("limit")?Values.number(args,"limit"):10;if(limit<1||limit>10)throw CommunityException.invalid();List<Map<String,Object>> result=new ArrayList<>();boolean[] more={false};store.tx(db->{try(var q=db.prepareStatement("SELECT id FROM ecosystem_critical WHERE id>? AND state IN ('PENDING','APPROVED') AND expires>? ORDER BY id LIMIT ?")){q.setString(1,after);q.setLong(2,System.currentTimeMillis());q.setLong(3,limit+1);try(var r=q.executeQuery()){while(r.next()){if(result.size()==limit){more[0]=true;break;}result.add(metadata(r.getString(1)));}}}return null;});return Map.of("items",result,"requests",result,"nextAfter",more[0]?result.getLast().get("id"):"");}
    private static Map<String,Object> identityProof(CommunityIdentityBridge600.Evidence e,Map<String,Object> auth)throws Exception {if(auth==null||!auth.keySet().equals(Set.of("time","nonce","proof")))throw CommunityException.denied();long time=StrictJson.number(auth,"time",0,Long.MAX_VALUE);String nonce=IdentityProtocol.nonceValue(StrictJson.text(auth,"nonce",43));byte[] proof=IdentityProtocol.unb64(StrictJson.text(auth,"proof",86),64);Map<String,Object> rpc=new LinkedHashMap<>();rpc.put("capability",e.capability);rpc.put("time",time);rpc.put("nonce",nonce);rpc.put("proof",IdentityProtocol.b64(proof));return rpc;}
}
